/// Strokes for one character, or None if it is not a bank character.
pub fn strokes(ch: &str) -> Option<u8> {
    STROKES
        .binary_search_by(|(k, _)| (*k).cmp(ch))
        .ok()
        .map(|i| STROKES[i].1)
}

/// The heaviest character in a word — a word is as hard to write as its worst
/// character, not its average.
pub fn word_strokes(word: &str) -> Option<u8> {
    let mut worst = None;
    for c in word.chars().filter(|c| !c.is_ascii()) {
        let n = strokes(&c.to_string())?;
        worst = Some(worst.map_or(n, |w: u8| w.max(n)));
    }
    worst
}

/// CC-CJK-INK F5 — the writing Climb.
///
/// Four tiers by stroke count, and the boundaries are not arbitrary: F1
/// measured real handwriting and every miss was thirteen strokes or more, while
/// everything at twelve and under came back. So the ladder is cut where the
/// recogniser's reliability actually changes rather than at round numbers.
///
///   1  1-4    kana and the simplest characters — F1: no misses
///   2  5-8    the bulk of everyday hanzi        — F1: no misses
///   3  9-12   still solid                       — F1: no misses
///   4  13+    the dense tail                    — F1: every miss lived here
pub fn writing_tier(strokes: u8) -> u8 {
    match strokes {
        0..=4 => 1,
        5..=8 => 2,
        9..=12 => 3,
        _ => 4,
    }
}

/// F4's gate, which could not be built until this table existed: is this word
/// one the recogniser can be trusted with?
///
/// Tier 4 is where every F1 miss lived. Offering a drawn round there is not
/// harmful — practice records nothing — but it is discouraging, so it waits
/// until the recogniser improves or a stroke-based one replaces it (D2).
pub fn writing_ready(word: &str) -> bool {
    word_strokes(word).is_some_and(|n| writing_tier(n) < 4)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_and_complete_for_the_banks() {
        let mut keys: Vec<&str> = STROKES.iter().map(|(k, _)| *k).collect();
        let orig = keys.clone();
        keys.sort_unstable();
        assert_eq!(keys, orig, "generated table must ship sorted for binary search");
        // Every character the banks can ask a player to write has a count.
        let mut missing = Vec::new();
        for lang in ["zh", "ja"] {
            for tier in ["easy", "medium", "hard", "expert"] {
                for entry in crate::words::tier_for(lang, tier) {
                    let shown = entry.split('|').nth(1).unwrap_or(entry);
                    for c in shown.chars().filter(|c| !c.is_ascii()) {
                        if strokes(&c.to_string()).is_none() {
                            missing.push(c);
                        }
                    }
                }
            }
        }
        missing.dedup();
        assert!(missing.is_empty(), "no stroke count for {missing:?}");
    }

    /// D5 monotonicity, the same law the picture manifests already obey: a
    /// higher tier is never easier to write than a lower one.
    #[test]
    fn tiers_are_monotone_by_construction() {
        let mut last = 0;
        for n in 1u8..=30 {
            let t = writing_tier(n);
            assert!(t >= last, "tier fell from {last} to {t} at {n} strokes");
            last = t;
        }
        assert_eq!(writing_tier(1), 1);
        assert_eq!(writing_tier(12), 3);
        assert_eq!(writing_tier(13), 4, "F1 put every miss at 13 strokes or more");
    }

    #[test]
    fn a_word_is_as_hard_as_its_worst_character() {
        // 帮助: 帮 is 9, 助 is 7 — the word is a 9, not an 8.
        assert_eq!(word_strokes("帮助"), Some(9));
        assert_eq!(word_strokes("八"), Some(2));
        assert_eq!(word_strokes("nothing here"), None);
    }

    #[test]
    fn the_gate_matches_what_f1_measured() {
        // Everything F1 missed was tier 4 and is held back.
        for w in ["警", "議", "験", "曜", "語", "蓝", "餐"] {
            assert!(!writing_ready(w), "{w} was an F1 miss and must not be offered");
        }
        // Everything simple it read is offered.
        for w in ["八", "日", "山", "川", "水", "火", "あ", "き"] {
            assert!(writing_ready(w), "{w} read fine in F1 and should be offered");
        }
    }
}
